// Lógica robusta de cotización para CleanPro
const rawItems = $input.first().json.items || [];
const clienteId = $input.first().json.cliente_id;

// Catálogo de precios de referencia sincronizado con Google Sheets
const preciosBase = {
  'desengrasante industrial 20l': 25400,
  'papel institucional x12': 8200,
  'detergente concentrado 5l': 6100,
  'bolsas residuo 120l (x50)': 9700,
  'alcohol en gel 5l': 11300,
  'lavandina industrial 10l': 7500,
  'guantes de nitrilo (caja x100)': 15800
};

let subtotal = 0;
const detalle = [];
let itemsInvalidos = 0;

for (const item of rawItems) {
  // Normalizamos el nombre del producto recibido (minúsculas y sin espacios extra) para asegurar el match
  const productoLimpio = (item.producto || '').trim().toLowerCase();
  const precioUnit = preciosBase[productoLimpio] || 0;

  // Validamos que la cantidad sea un número válido y mayor a 0
  const cantidad = Number(item.cantidad);

  if (precioUnit > 0 && !isNaN(cantidad) && cantidad > 0) {
    const totalItem = precioUnit * cantidad;
    subtotal += totalItem;
    detalle.push({ 
      producto: item.producto, 
      cantidad: cantidad, 
      precio_unitario: precioUnit,
      subtotal: totalItem 
    });
  } else {
    itemsInvalidos++;
  }
}

// Si no se pudo procesar ningún ítem correctamente, devolvemos un estado de error controlado
if (detalle.length === 0) {
  return [{
    json: {
      status: 'error',
      data: {
        mensaje: 'No se pudieron reconocer los productos o las cantidades solicitadas en el catálogo.'
      }
    }
  }];
}

// Regla de descuento por volumen (determinista)
let descuentoPct = 0;
if (subtotal >= 250000) descuentoPct = 0.08;
else if (subtotal >= 100000) descuentoPct = 0.05;

const totalFinal = subtotal * (1 - descuentoPct);
const cotizacionId = 'COT-2026-' + Math.floor(1000 + Math.random() * 9000);

const borrador = `Estimado cliente (${clienteId}), adjuntamos el detalle de su cotización ${cotizacionId}. Total estimado: ARS ${totalFinal.toLocaleString('es-AR')}. Descuento aplicado: ${(descuentoPct*100).toFixed(0)}% por compra mayorista.`;

return [{
  json: {
    status: 'success',
    data: {
      cotizacion_id: cotizacionId,
      total_estimado: 'ARS ' + totalFinal.toLocaleString('es-AR'),
      descuento_aplicado: (descuentoPct*100).toFixed(0) + '% (compra mayorista)',
      detalle_items: detalle,
      borrador_email: borrador
    }
  }
}];
